"""Channel controller protocol for voice event-composition handlers.

Handlers hold no reference to the websocket, so they act on the channel through this
protocol, which a channel implements and injects into them.
"""

from __future__ import annotations

from enum import Enum
from typing import Protocol, runtime_checkable


class ChannelCommand(Enum):
    """A channel action a core handler can ask the owning channel to perform.

    The controller is a command bridge from core handlers back to the channel, so each
    member names one concrete channel action rather than adding another method to the
    protocol.
    """

    HANGUP = "hangup"


@runtime_checkable
class ChannelController(Protocol):
    """Actions a core handler may ask the owning channel to perform.

    A handler invokes a single :class:`ChannelCommand`; the implementation the voice
    channel builds per call maps it to a concrete channel call.
    """

    async def invoke(self, command: ChannelCommand) -> None:
        """Run the channel action named by ``command``."""
        ...
